/// Each agent's mark, by its runtime id (`runtimeMarks.ts`).
pub fn mark(runtime: &str) -> Option<&'static Icon> {
    match runtime {
        "acp" => Some(&MARK_ACP),
        "antigravity" => Some(&MARK_ANTIGRAVITY),
        "claude" => Some(&MARK_CLAUDE),
        "codex" => Some(&MARK_CODEX),
        "copilot" => Some(&MARK_COPILOT),
        "cursor" => Some(&MARK_CURSOR),
        "gemini" => Some(&MARK_GEMINI),
        "kilo" => Some(&MARK_KILO),
        "muse" => Some(&MARK_MUSE),
        "opencode" => Some(&MARK_OPENCODE),
        _ => None,
    }
}

pub static RUNTIMES: &[&str] = &["acp", "antigravity", "claude", "codex", "copilot", "cursor", "gemini", "kilo", "muse", "opencode"];

